<?php
function page_start(string $title, string $active=''): void {
    $version=trim(file_get_contents(ROOT.'/VERSION'));
    $nav=['dashboard.php'=>'À traiter','index.php'=>'Actualités','vulprod.php'=>'Vulnérabilités','favorites.php'=>'Favoris','sources.php'=>'Sources'];
    ?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title><?=e($title)?> · Actu Cyber &amp; IT</title><link rel="stylesheet" href="<?=e(base_path())?>/assets/app.css"><script src="<?=e(base_path())?>/assets/app.js" defer></script></head><body><a class="skip" href="#main">Aller au contenu</a><header class="site-header"><div class="header-inner"><a class="brand" href="<?=e(base_path())?>/index.php"><span class="brand-icon">A</span><span>ACTU<span class="brand-sub">CYBER &amp; IT</span></span></a><nav aria-label="Navigation principale"><?php foreach ($nav as $path=>$label): ?><a <?= $active===$path?'aria-current="page"':'' ?> href="<?=e(base_path())?>/<?=e($path)?>"><?=e($label)?></a><?php endforeach ?></nav><div class="header-tools"><button type="button" id="theme" class="secondary" aria-label="Changer le thème">Thème</button><a class="button secondary" href="<?=e(base_path())?>/admin.php">Administration</a><?php if(is_admin()):?><form method="post" action="<?=e(base_path())?>/logout.php"><?=csrf_field()?><button class="secondary">Déconnexion</button></form><?php endif ?></div></div></header><main id="main" class="container"><?php
    if (isset($_SESSION['flash'])) { ?><p class="notice" role="status"><?=e($_SESSION['flash'])?></p><?php unset($_SESSION['flash']); }
}
function page_end(): void { ?><footer class="site-footer"><span>Actu Cyber &amp; IT · v<?=e(trim(file_get_contents(ROOT.'/VERSION')))?> · Veille indépendante</span><span><a href="<?=e(base_path())?>/privacy.php">Confidentialité</a> · <a href="<?=e(base_path())?>/release.php">Versions</a></span></footer></body></html><?php }
function heading(string $eyebrow,string $title,string $desc): void { ?><section class="page-heading"><p class="eyebrow"><?=e($eyebrow)?></p><h1><?=e($title)?></h1><p class="lead"><?=e($desc)?></p></section><?php }
function filters_form(array $f,bool $vuln): void { ?><form class="filter-panel" method="get"><div class="filter-search"><label for="q">Rechercher un sujet, un produit ou une CVE</label><input id="q" type="search" name="q" value="<?=e($f['q'])?>" placeholder="Ex. ransomware, Linux, CVE-2026…"></div><div><label for="cat">Catégorie</label><select id="cat" name="cat"><option value="">Toutes les catégories</option><?php foreach(['cyber'=>'Cybersécurité','it'=>'Informatique','linux'=>'Linux','vulprod'=>'Vulnérabilités'] as $k=>$v):?><option value="<?=$k?>" <?=$f['cat']===$k?'selected':''?>><?=$v?></option><?php endforeach ?></select></div><div><label for="src">Source</label><select id="src" name="src"><option value="">Toutes les sources</option><?php foreach(run('SELECT id,name FROM sources ORDER BY name')->fetchAll() as $s):?><option value="<?=$s['id']?>" <?=$f['src']===(string)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach ?></select></div><div><label for="period">Période</label><select id="period" name="period"><option value="">Tout l’historique</option><?php foreach(['1'=>'24 heures','7'=>'7 jours','30'=>'30 jours'] as $k=>$v):?><option value="<?=$k?>" <?=$f['period']===(string)$k?'selected':''?>><?=$v?></option><?php endforeach ?></select></div><?php if($vuln):?><div><label for="sort">Classement</label><select id="sort" name="sort"><option value="latest">Plus récent</option><option value="severity" <?=($f['sort']??'')==='severity'?'selected':''?>>CVSS le plus élevé</option></select></div><?php endif ?><?php if(($f['cve']??'')!==''):?><input type="hidden" name="cve" value="<?=e($f['cve'])?>"><p>Dossier : <?=e($f['cve'])?></p><?php endif ?><div class="filter-bottom"><label class="check"><input type="checkbox" name="tracked" value="1" <?=($f['tracked']??'')==='1'?'checked':''?>> Mes technologies</label><label class="check"><input type="checkbox" name="unread" value="1" <?=$f['unread']==='1'?'checked':''?>> Non lus uniquement</label><?php if($vuln):?><label class="check"><input type="checkbox" name="kev" value="1" <?=$f['kev']==='1'?'checked':''?>> Exploitation connue (CISA)</label><?php endif ?><button>Appliquer les filtres</button><a href="<?=e(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH))?>">Réinitialiser</a></div></form><?php }
function article_card(array $a): void {
    ?><article class="article-card <?=$a['is_read']?'is-read':''?>"><div class="card-meta"><span class="badge"><?=e($a['category'])?></span><span><?=e($a['source'])?></span><time datetime="<?=date(DATE_ATOM,(int)$a['published'])?>"><?=e(when((int)$a['published']))?></time></div><h2><a href="<?=e($a['url'])?>" target="_blank" rel="noopener noreferrer"><?=e($a['title'])?><span class="external" aria-label="Nouvel onglet"> ↗</span></a></h2><p class="summary"><?=e($a['summary'])?></p><div class="cve-tags"><?php foreach(article_cves((int)$a['id']) as $c):?><a href="<?=e(base_path())?>/vulprod.php?cve=<?=e($c['id'])?>" class="badge <?=$c['exploited']?'danger':''?>"><?=e($c['id'])?><?=$c['exploited']?' · Exploitée':''?><?=$c['cvss']!==null?' · CVSS '.e($c['cvss']):' · CVSS non renseigné'?></a><?php endforeach ?></div><div class="card-actions"><form method="post" action="<?=e(base_path())?>/action.php"><?=csrf_field()?><input type="hidden" name="article" value="<?=$a['id']?>"><button class="text-button" name="action" value="favorite" aria-pressed="<?=$a['favorite']?'true':'false'?>"><?=$a['favorite']?'★ En favori':'☆ Ajouter aux favoris'?></button><button class="text-button" name="action" value="read" aria-pressed="<?=$a['is_read']?'true':'false'?>"><?=$a['is_read']?'✓ Lu · annuler':'Marquer comme lu'?></button></form><?php if(is_admin()):?><a class="text-button" href="<?=e(base_path())?>/ai.php?id=<?=$a['id']?>">Résumé IA</a><?php endif ?><?php if($a['author']):?><small><?=e($a['author'])?></small><?php endif ?></div></article><?php
}
function admin_nav(string $active): void { ?><nav class="subnav" aria-label="Administration"><?php foreach(['admin.php'=>'Tableau de bord','manage.php'=>'Gestion des sources','alerts.php'=>'Alertes','analytics.php'=>'Statistiques','diagnostics.php'=>'Diagnostic','settings.php'=>'Paramètres IA'] as $path=>$label):?><a href="<?=e(base_path())?>/<?=$path?>" <?=$path===$active?'aria-current="page"':''?>><?=$label?></a><?php endforeach ?></nav><?php }
